  render: () => {
    const root = document.createElement('div');
    root.style.cssText = ROOT_STYLE;
    const info = document.createElement('div');
    info.style.cssText = INFO_STYLE;
    info.innerHTML = ['<strong>Intentional validation errors:</strong>', '1. <em>Precedence violation</em> \\u2014 R16 is placed before R32 in the same draw (Boys U16 Singles Main)', '2. <em>Duplicate round</em> \\u2014 R16 appears in both Venue A and Venue B', 'Check the Issues panel (left) for details and fix actions.'].join('<br>');
    root.appendChild(info);
    const container = document.createElement('div');
    root.appendChild(container);
    const control = createSchedulingProfile(makeBaseConfig({
      initialProfile: ERROR_PROFILE,
      onFixAction: action => {
        console.log('Fix action delegated to host:', action.kind, action);
      }
    }), container);
    addConsoleLog(root, control);
    return root;
  }
